```typescript
import { Dashboard, User, Permission } from '@/types';

export function canComment(dashboard: Dashboard, user: User): boolean {
  if (!user || !dashboard) return false;
  if (dashboard.ownerId === user.id) return true;
  const permission = dashboard.permissions?.find(p => p.userId === user.id);
  return permission?.level === 'comment' || permission?.level === 'edit';
}

export function canEdit(dashboard: Dashboard, user: User): boolean {
  if (!user || !dashboard) return false;
  if (dashboard.ownerId === user.id) return true;
  const permission = dashboard.permissions?.find(p => p.userId === user.id);
  return permission?.level === 'edit';
}

export function isOwner(dashboard: Dashboard, user: User): boolean {
  if (!user || !dashboard) return false;
  return dashboard.ownerId === user.id;
}

export function canPublish(dashboard: Dashboard, user: User): boolean {
  // Only owner can publish/unpublish per spec
  return isOwner(dashboard, user);
}

export function canShare(dashboard: Dashboard, user: User): boolean {
  // Owner or edit permission can share
  return isOwner(dashboard, user) || canEdit(dashboard, user);
}
```

**Create React hook:** `hooks/use-dashboard-permissions.ts`

```typescript
import { useMemo } from 'react';
import { useCurrentUser } from '@/hooks/use-current-user';
import { Dashboard } from '@/types';
import * as perms from '@/lib/permissions/dashboard-permissions';

export function useDashboardPermissions(dashboard: Dashboard | null) {
  const user = useCurrentUser();

  return useMemo(() => {
    if (!dashboard || !user) {
      return {
        canComment: false,
        canEdit: false,
        isOwner: false,
        canPublish: false,
        canShare: false,
      };
    }

    return {
      canComment: perms.canComment(dashboard, user),
      canEdit: perms.canEdit(dashboard, user),
      isOwner: perms.isOwner(dashboard, user),
      canPublish: perms.canPublish(dashboard, user),
      canShare: perms.canShare(dashboard, user),
    };
  }, [dashboard, user]);
}
```

**Update:** `components/workspace/dashboard-popup.tsx`

**Toolbar structure:**
```tsx
import { useDashboardPermissions } from '@/hooks/use-dashboard-permissions';
import { MessageSquare, Globe, Edit, Share2 } from 'lucide-react';

function DashboardPopupToolbar({ dashboard }: { dashboard: Dashboard }) {
  const permissions = useDashboardPermissions(dashboard);
  const [showAccessDialog, setShowAccessDialog] = useState(false);
  const [requestType, setRequestType] = useState<'comment' | 'edit'>('edit');

  const handleCommentsClick = () => {
    if (permissions.canComment) {
      // Toggle comments panel
      toggleCommentsPanel();
    } else {
      setRequestType('comment');
      setShowAccessDialog(true);
    }
  };

  const handlePublishClick = () => {
    if (permissions.canPublish) {
      // Execute publish/unpublish
      togglePublishStatus(dashboard.id);
    } else {
      setRequestType('edit');
      setShowAccessDialog(true);
    }
  };

  const handleEditClick = () => {
    if (permissions.canEdit) {
      // Navigate to editor
      router.push(`/dashboard/${dashboard.id}/edit`);
    } else {
      setRequestType('edit');
      setShowAccessDialog(true);
    }
  };

  const handleShareClick = () => {
    if (permissions.canShare) {
      // Open share dialog
      setShowShareDialog(true);
    } else {
      setRequestType('edit');
      setShowAccessDialog(true);
    }
  };

  return (
    <div className="toolbar">
      <Button onClick={handleCommentsClick} variant="ghost">
        <MessageSquare /> Comments
      </Button>
      <Button onClick={handlePublishClick} variant="ghost">
        <Globe /> {dashboard.lifecycleStatus === 'published' ? 'Unpublish' : 'Publish'}
      </Button>
      <Button onClick={handleEditClick} variant="ghost">
        <Edit /> Edit
      </Button>
      <Button onClick={handleShareClick} variant="ghost">
        <Share2 /> Share
      </Button>

      <AccessRequestDialog
        isOpen={showAccessDialog}
        onClose={() => setShowAccessDialog(false)}
        dashboardId={dashboard.id}
        requestedPermission={requestType}
        dashboardTitle={dashboard.title}
      />
    </div>
  );
}
```

